def compute(vars):
    goodwill = vars["v1"]
    net_assets_acquired = vars["v2"]

    if net_assets_acquired == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": None, "unit": "percentage"}}}

    ratio = goodwill / net_assets_acquired
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "goodwill": goodwill,
            "net_assets_acquired": net_assets_acquired,
            "ratio": ratio,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"},
        },
    }
